// Xcompiler: the geometry census ("census <n> [frames]" in xnative_skip.txt, new n = new request;
// tools/halo3-gpu-censo.ps1). Over the next whole frames (default 20), per vertex shader + pixel
// shader + pass + guest primitive type: draws, elements sent to the GPU (indices, or the vertices
// of a non-indexed draw) and, for the indexed draws whose indices the recorder holds, the vertices
// those indices span (max - min + 1: what a GPU that shades the whole index range works on) and
// the distinct vertices they name. Written to xnative_census.txt in the app's files folder:
//   census <n> frames <frames> ms <milliseconds>
//   d <vs> <ps> <pass> <primitive> <flags> <draws> <elements> <span draws> <span> <distinct>
//   end <n>
// flags: 1 indexed, 2 computed-fetch vertex shader, 4 writes color, 8 writes depth, 16 blends.
struct NativeGeometryCensus {
  struct Key {
    uint64_t vs = 0, ps = 0;
    uint32_t pass = 0, primitive = 0, flags = 0;
    auto operator<=>(const Key&) const = default;
  };
  struct Row {
    uint64_t draws = 0, elements = 0, span_draws = 0, span = 0, distinct = 0;
  };
  std::mutex mutex;
  std::map<Key, Row> rows;
  uint64_t request = 0;
  uint32_t frames_wanted = 0, frames_done = 0, last_frame = 0;
  // 0 waiting for the first draw, 1 inside the partial frame the request arrived in, 2 counting.
  uint32_t stage = 0;
  std::chrono::steady_clock::time_point started{};
};
static NativeGeometryCensus g_census;
static std::atomic<bool> g_census_active{false};
// The index span and distinct vertices of the indexed draw this thread is recording
// (RecordIndexedPrimitive, just before the draw is observed); 0 = not known.
static thread_local uint32_t g_census_span = 0;
static thread_local uint32_t g_census_distinct = 0;

static void StartNativeGeometryCensus(uint64_t request, uint32_t frames) {
  std::lock_guard lock(g_census.mutex);
  if (!request || request == g_census.request) return;
  g_census.rows.clear();
  g_census.request = request;
  g_census.frames_wanted = std::clamp(frames ? frames : 20u, 1u, 600u);
  g_census.frames_done = 0;
  g_census.stage = 0;
  g_census_active.store(true, std::memory_order_release);
}

static void ObserveNativeGeometryCensus(const NativeGeometryCensus::Key& key, uint32_t elements,
                                        uint32_t span, uint32_t distinct, uint32_t frame) {
  std::lock_guard lock(g_census.mutex);
  if (!g_census_active.load(std::memory_order_relaxed)) return;
  if (g_census.stage == 0) {
    g_census.stage = 1;
    g_census.last_frame = frame;
  }
  if (frame != g_census.last_frame) {
    g_census.last_frame = frame;
    if (g_census.stage == 1) {
      g_census.stage = 2;
      g_census.started = std::chrono::steady_clock::now();
    } else if (++g_census.frames_done >= g_census.frames_wanted) {
      g_census_active.store(false, std::memory_order_release);
      const long long milliseconds = std::chrono::duration_cast<std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - g_census.started).count();
      const char* home = std::getenv("XDG_DATA_HOME");
      if (home && *home) {
        const std::filesystem::path folder(home);
        const std::filesystem::path temporary = folder / "xnative_census.txt.tmp";
        if (FILE* file = std::fopen(temporary.string().c_str(), "w")) {
          std::fprintf(file, "census %llu frames %u ms %lld\n",
                       (unsigned long long)g_census.request, g_census.frames_done, milliseconds);
          for (const auto& [row_key, row] : g_census.rows) {
            std::fprintf(file, "d %016llX %016llX %08X %u %u %llu %llu %llu %llu %llu\n",
                         (unsigned long long)row_key.vs, (unsigned long long)row_key.ps,
                         row_key.pass, row_key.primitive, row_key.flags,
                         (unsigned long long)row.draws, (unsigned long long)row.elements,
                         (unsigned long long)row.span_draws, (unsigned long long)row.span,
                         (unsigned long long)row.distinct);
          }
          std::fprintf(file, "end %llu\n", (unsigned long long)g_census.request);
          std::fclose(file);
          std::error_code error;
          std::filesystem::rename(temporary, folder / "xnative_census.txt", error);
        }
      }
      REXLOG_INFO("xnative-census: request {} written, {} frames, {} rows", g_census.request,
                  g_census.frames_done, g_census.rows.size());
      g_census.rows.clear();
      return;
    }
  }
  if (g_census.stage != 2) return;
  NativeGeometryCensus::Row& row = g_census.rows[key];
  ++row.draws;
  row.elements += elements;
  if (span) {
    ++row.span_draws;
    row.span += span;
    row.distinct += distinct;
  }
}
