// Background pipeline compiles (Halo 3 on the Mali, where one could take minutes): which
// pipeline each compile worker is in and since when, for the "draws skipped" log line, and every
// compile over a second logged with its shaders.
constexpr int kPipelineCompileSlots = 4;
std::atomic<uint64_t> g_pipeline_compile_vs[kPipelineCompileSlots];
std::atomic<uint64_t> g_pipeline_compile_ps[kPipelineCompileSlots];
std::atomic<uint64_t> g_pipeline_compile_since[kPipelineCompileSlots];
std::atomic<int> g_pipeline_compile_next_slot{0};
int PipelineCompileSlot() {
  thread_local const int slot = g_pipeline_compile_next_slot.fetch_add(1) % kPipelineCompileSlots;
  return slot;
}
void NotePipelineCompileBegin(uint64_t vs, uint64_t ps) {
  const int slot = PipelineCompileSlot();
  g_pipeline_compile_vs[slot].store(vs, std::memory_order_relaxed);
  g_pipeline_compile_ps[slot].store(ps, std::memory_order_relaxed);
  g_pipeline_compile_since[slot].store(rex::chrono::Clock::QueryHostTickCount(),
                                       std::memory_order_release);
}
void NotePipelineCompileEnd(uint64_t vs, uint64_t ps, uint64_t ticks, VkResult result) {
  g_pipeline_compile_since[PipelineCompileSlot()].store(0, std::memory_order_release);
  const uint64_t frequency = rex::chrono::Clock::QueryHostTickFrequency();
  const uint64_t ms = frequency ? ticks * 1000 / frequency : 0;
  if (ms >= 1000) {
    REXLOG_WARN("xnative-pipeline: vs={:016X} ps={:016X} took {} ms to compile{}", vs, ps, ms,
                result == VK_SUCCESS ? "" : " (failed)");
  }
}
std::string PipelineCompilesInProgress() {
  std::string text;
  const uint64_t now = rex::chrono::Clock::QueryHostTickCount();
  const uint64_t frequency = rex::chrono::Clock::QueryHostTickFrequency();
  for (int slot = 0; slot < kPipelineCompileSlots && frequency; ++slot) {
    const uint64_t since = g_pipeline_compile_since[slot].load(std::memory_order_acquire);
    if (!since || now < since) {
      continue;
    }
    text += fmt::format(" [compiling vs={:016X} ps={:016X} for {} ms]",
                        g_pipeline_compile_vs[slot].load(std::memory_order_relaxed),
                        g_pipeline_compile_ps[slot].load(std::memory_order_relaxed),
                        (now - since) * 1000 / frequency);
  }
  return text;
}

// Gears of War 3 (XNATIVE_FRAGMENT_READ_BARRIERS, Android default): the barrier that makes a
// resolved or copied image readable waits for the fragment shaders only. Naming the vertex
// stage there made the Mali finish all queued fragment work before the next pass could start
// its geometry, ~45 times a frame. A draw whose vertex shader samples textures adds that
// dependency first (one memory barrier outside the pass, while one is pending). Recorder thread.
std::atomic<bool> g_vertex_visibility_pending{false};
std::atomic<uint32_t> g_vertex_visibility_barriers{0}, g_vertex_visibility_splits{0};
bool FragmentOnlyReadBarriers() {
#if (XPORT_TITLE_ID == 0x4D5308AB || XPORT_TITLE_ID == 0x4D5307E6)
  static const bool enabled = [] {
    const char* value = std::getenv("XNATIVE_FRAGMENT_READ_BARRIERS");
    if (value && *value) return *value == '1';
#ifdef __ANDROID__
    return true;
#else
    return false;
#endif
  }();
  return enabled;
#else
  return false;
#endif
}
// The destination stages of a barrier that makes a fragment- or transfer-written image
// readable by later shaders.
VkPipelineStageFlags ShaderReadStagesAfterWrite() {
  if (FragmentOnlyReadBarriers()) {
    g_vertex_visibility_pending.store(true, std::memory_order_relaxed);
    return VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT;
  }
  return VK_PIPELINE_STAGE_VERTEX_SHADER_BIT | VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT;
}
// (XNATIVE_DRAW_TRACE) the trace file while the command being recorded is traced: its draw adds
// the attachments it really renders to.
FILE* g_draw_trace_host = nullptr;
// (dynamic resolution) time the recorder waited for the GPU to free a frame slot, the
// sign that the GPU, not the CPU, holds the frame.
std::atomic<uint64_t> g_gpu_slot_wait_ns{0};
struct ResolutionPreset {
  const char* name;
  std::array<double, 4> scales;  // highest first
  uint32_t count;
};
constexpr ResolutionPreset kResolutionPresets[] = {
    {"nativa", {1.0}, 1},
    {"alta", {1.0, 0.92, 0.85}, 3},
    {"equilibrada", {1.0, 0.9, 0.8, 0.7}, 4},
    {"rendimiento", {0.85, 0.75, 0.67, 0.6}, 4},
    {"bateria", {0.7, 0.6, 0.5}, 3},
};
std::atomic<uint64_t> g_resolve_swaps_planned{0}, g_resolve_swaps_fast{0};
std::atomic<uint64_t> g_present_from_surface{0};
// TEMP: first failing condition of resolve swaps (A2) and surface presents (A11).
std::array<std::atomic<uint32_t>, 32> g_resolve_swap_rejects{}, g_present_surface_rejects{};
std::mutex g_resolve_kinds_mutex;
std::map<std::string, uint32_t> g_resolve_kinds;
void NoteResolveKind(std::string key) {
  std::lock_guard lock(g_resolve_kinds_mutex);
  ++g_resolve_kinds[std::move(key)];
}

// Hot producer/worker/recorder critical sections last microseconds, but bionic parks a
// contended locker in the kernel at once and the futex wakeup costs far more
// than the wait. Spin briefly before blocking.
uint32_t MaxQueuedTitlePresents() {
  return std::clamp<uint32_t>(REXCVAR_GET(xnative_max_queued_frames), 1, 4);
}

std::unique_lock<std::mutex> LockWithSpin(std::mutex& mutex) {
  std::unique_lock lock(mutex, std::defer_lock);
  for (int attempt = 0; attempt < 512; ++attempt) {
    if (lock.try_lock()) return lock;
#if defined(__aarch64__)
    asm volatile("yield");
#endif
  }
  lock.lock();
  return lock;
}


// The diagnostics policy is configured once at startup and never changes, but
// asking it is a call into the runtime library; the recorder asks dozens of
// times per draw. Cached once the policy is configured.
bool CachedDiagnosticsEnabled(rex::diagnostics::Category category) noexcept {
  static std::atomic<uint32_t> cached_mask{0};  // bit 31: cached
  uint32_t mask = cached_mask.load(std::memory_order_relaxed);
  if (!(mask & 0x80000000u)) [[unlikely]] {
    if (!rex::diagnostics::IsConfigured()) return rex::diagnostics::IsEnabled(category);
    mask = 0x80000000u;
    for (uint32_t i = 0; i < uint32_t(rex::diagnostics::Category::kCount) && i < 31; ++i)
      if (rex::diagnostics::IsEnabled(rex::diagnostics::Category(i))) mask |= 1u << i;
    cached_mask.store(mask, std::memory_order_relaxed);
  }
  return (mask >> uint32_t(category)) & 1u;
}
namespace gpu_flight = rex::diagnostics::gpu_flight;

bool IsNativeFlightVerboseLoggingEnabled() {
  return CachedDiagnosticsEnabled(rex::diagnostics::Category::kNativeTrace) ||
         CachedDiagnosticsEnabled(rex::diagnostics::Category::kVulkan);
}





























template <typename Handle>
uint64_t NativeVulkanHandleIdentity(Handle handle) {
  if constexpr (std::is_pointer_v<Handle>) {
    return uint64_t(reinterpret_cast<uintptr_t>(handle));
  } else {
    return uint64_t(handle);
  }
}

struct NativeImageLayoutSynchronization {
  VkAccessFlags access = 0;
  VkPipelineStageFlags stages = VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT;
};

NativeImageLayoutSynchronization ColorImageLayoutSynchronization(VkImageLayout layout) {
  switch (layout) {
    case VK_IMAGE_LAYOUT_UNDEFINED:
      return {};
    case VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL:
      return {VK_ACCESS_SHADER_READ_BIT,
              VK_PIPELINE_STAGE_VERTEX_SHADER_BIT | VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT};
    case VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL:
      return {VK_ACCESS_COLOR_ATTACHMENT_READ_BIT | VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT,
              VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT};
    case VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL:
      return {VK_ACCESS_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_TRANSFER_BIT};
    case VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL:
      return {VK_ACCESS_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_TRANSFER_BIT};
    default:
      return {VK_ACCESS_MEMORY_READ_BIT | VK_ACCESS_MEMORY_WRITE_BIT,
              VK_PIPELINE_STAGE_ALL_COMMANDS_BIT};
  }
}

NativeImageLayoutSynchronization DepthImageLayoutSynchronization(VkImageLayout layout) {
  switch (layout) {
    case VK_IMAGE_LAYOUT_UNDEFINED:
      return {};
    case VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL:
    case VK_IMAGE_LAYOUT_DEPTH_STENCIL_READ_ONLY_OPTIMAL:
      return {VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_READ_BIT,
              VK_PIPELINE_STAGE_VERTEX_SHADER_BIT | VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT |
                  VK_PIPELINE_STAGE_EARLY_FRAGMENT_TESTS_BIT |
                  VK_PIPELINE_STAGE_LATE_FRAGMENT_TESTS_BIT};
    case VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL:
      return {
          VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_READ_BIT |
              VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT,
          VK_PIPELINE_STAGE_EARLY_FRAGMENT_TESTS_BIT | VK_PIPELINE_STAGE_LATE_FRAGMENT_TESTS_BIT};
    case VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL:
      return {VK_ACCESS_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_TRANSFER_BIT};
    case VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL:
      return {VK_ACCESS_TRANSFER_WRITE_BIT, VK_PIPELINE_STAGE_TRANSFER_BIT};
    default:
      return {VK_ACCESS_MEMORY_READ_BIT | VK_ACCESS_MEMORY_WRITE_BIT,
              VK_PIPELINE_STAGE_ALL_COMMANDS_BIT};
  }
}

const char* NativeFrameSlotStateName(NativeFrameContextRing::SlotState state) {
  switch (state) {
    case NativeFrameContextRing::SlotState::kAvailable:
      return "available";
    case NativeFrameContextRing::SlotState::kRecording:
      return "recording";
    case NativeFrameContextRing::SlotState::kPrepared:
      return "prepared";
    case NativeFrameContextRing::SlotState::kSubmitted:
      return "submitted";
    case NativeFrameContextRing::SlotState::kWaiting:
      return "waiting";
    case NativeFrameContextRing::SlotState::kReadyForReset:
      return "ready-for-reset";
  }
  return "unknown";
}

NativeImageLayoutSynchronization ImageLayoutSynchronization(VkImageLayout layout,
                                                            VkImageAspectFlags aspect) {
  return aspect & (VK_IMAGE_ASPECT_DEPTH_BIT | VK_IMAGE_ASPECT_STENCIL_BIT)
             ? DepthImageLayoutSynchronization(layout)
             : ColorImageLayoutSynchronization(layout);
}

struct NativeProcessMemorySnapshot {
  uint64_t physical_footprint_bytes = 0;
  uint64_t physical_footprint_peak_bytes = 0;
  uint64_t resident_bytes = 0;
  uint64_t resident_peak_bytes = 0;
  uint64_t virtual_bytes = 0;
  uint64_t internal_bytes = 0;
  uint64_t internal_peak_bytes = 0;
  uint64_t external_bytes = 0;
  uint64_t external_peak_bytes = 0;
  uint64_t reusable_bytes = 0;
  uint64_t reusable_peak_bytes = 0;
  uint64_t compressed_bytes = 0;
  uint64_t compressed_peak_bytes = 0;
  uint64_t device_bytes = 0;
  uint64_t device_peak_bytes = 0;
  uint64_t graphics_footprint_bytes = 0;
  uint64_t graphics_footprint_compressed_bytes = 0;
  uint64_t graphics_nofootprint_bytes = 0;
  uint64_t graphics_nofootprint_compressed_bytes = 0;
  uint64_t limit_bytes_remaining = 0;
  uint64_t region_count = 0;
  uint64_t page_size = 0;
  uint64_t malloc_blocks_in_use = 0;
  uint64_t malloc_in_use_bytes = 0;
  uint64_t malloc_peak_bytes = 0;
  uint64_t malloc_reserved_bytes = 0;
  uint64_t task_info_revision = 0;
  uint64_t vm_region_scan_complete = 0;
  uint64_t vm_region_scan_errors = 0;
  std::array<memory::ProcessVmRegionUsage, memory::kProcessVmCategoryCount> vm_regions{};
};

NativeProcessMemorySnapshot QueryNativeProcessMemorySnapshot(bool include_vm_regions = false) {
  NativeProcessMemorySnapshot snapshot;
#if defined(__APPLE__) && defined(__MACH__)
  const auto nonnegative = [](int64_t value) { return value > 0 ? uint64_t(value) : uint64_t(0); };
  task_vm_info_data_t task_vm_info{};
  mach_msg_type_number_t task_vm_info_count = TASK_VM_INFO_COUNT;
  if (task_info(mach_task_self(), TASK_VM_INFO, reinterpret_cast<task_info_t>(&task_vm_info),
                &task_vm_info_count) == KERN_SUCCESS) {
    snapshot.virtual_bytes = task_vm_info.virtual_size;
    snapshot.resident_bytes = task_vm_info.resident_size;
    snapshot.resident_peak_bytes = task_vm_info.resident_size_peak;
    snapshot.device_bytes = task_vm_info.device;
    snapshot.device_peak_bytes = task_vm_info.device_peak;
    snapshot.internal_bytes = task_vm_info.internal;
    snapshot.internal_peak_bytes = task_vm_info.internal_peak;
    snapshot.external_bytes = task_vm_info.external;
    snapshot.external_peak_bytes = task_vm_info.external_peak;
    snapshot.reusable_bytes = task_vm_info.reusable;
    snapshot.reusable_peak_bytes = task_vm_info.reusable_peak;
    snapshot.compressed_bytes = task_vm_info.compressed;
    snapshot.compressed_peak_bytes = task_vm_info.compressed_peak;
    snapshot.region_count = task_vm_info.region_count > 0 ? uint64_t(task_vm_info.region_count) : 0;
    snapshot.page_size = task_vm_info.page_size > 0 ? uint64_t(task_vm_info.page_size) : 0;
    if (task_vm_info_count >= TASK_VM_INFO_REV1_COUNT) {
      snapshot.physical_footprint_bytes = task_vm_info.phys_footprint;
      snapshot.task_info_revision = 1;
    }
    if (task_vm_info_count >= TASK_VM_INFO_REV2_COUNT) {
      snapshot.task_info_revision = 2;
    }
    if (task_vm_info_count >= TASK_VM_INFO_REV3_COUNT) {
      snapshot.physical_footprint_peak_bytes = nonnegative(task_vm_info.ledger_phys_footprint_peak);
      snapshot.graphics_footprint_bytes = nonnegative(task_vm_info.ledger_tag_graphics_footprint);
      snapshot.graphics_footprint_compressed_bytes =
          nonnegative(task_vm_info.ledger_tag_graphics_footprint_compressed);
      snapshot.graphics_nofootprint_bytes =
          nonnegative(task_vm_info.ledger_tag_graphics_nofootprint);
      snapshot.graphics_nofootprint_compressed_bytes =
          nonnegative(task_vm_info.ledger_tag_graphics_nofootprint_compressed);
      snapshot.task_info_revision = 3;
    }
    if (task_vm_info_count >= TASK_VM_INFO_REV4_COUNT) {
      snapshot.limit_bytes_remaining = task_vm_info.limit_bytes_remaining;
      snapshot.task_info_revision = 4;
    }
    if (task_vm_info_count >= TASK_VM_INFO_REV5_COUNT) {
      snapshot.task_info_revision = 5;
    }
    if (task_vm_info_count >= TASK_VM_INFO_REV6_COUNT) {
      snapshot.task_info_revision = 6;
    }
    if (task_vm_info_count >= TASK_VM_INFO_REV7_COUNT) {
      snapshot.task_info_revision = 7;
    }
  }

  if (!snapshot.resident_bytes || !snapshot.virtual_bytes) {
    mach_task_basic_info_data_t task_basic_info{};
    mach_msg_type_number_t task_basic_info_count = MACH_TASK_BASIC_INFO_COUNT;
    if (task_info(mach_task_self(), MACH_TASK_BASIC_INFO,
                  reinterpret_cast<task_info_t>(&task_basic_info),
                  &task_basic_info_count) == KERN_SUCCESS) {
      snapshot.resident_bytes = task_basic_info.resident_size;
      snapshot.resident_peak_bytes = task_basic_info.resident_size_max;
      snapshot.virtual_bytes = task_basic_info.virtual_size;
    }
  }

  malloc_statistics_t malloc_statistics{};
  malloc_zone_statistics(nullptr, &malloc_statistics);
  snapshot.malloc_blocks_in_use = malloc_statistics.blocks_in_use;
  snapshot.malloc_in_use_bytes = malloc_statistics.size_in_use;
  snapshot.malloc_peak_bytes = malloc_statistics.max_size_in_use;
  snapshot.malloc_reserved_bytes = malloc_statistics.size_allocated;

  // The detailed region walk can traverse thousands of mappings and is intended only for the
  // low-frequency memory profiler. Keep the existing per-frame performance profiler on the cheap
  // TASK_VM_INFO and malloc-zone counters.
  if (!include_vm_regions) {
    return snapshot;
  }

  const auto classify_region = [](uint32_t tag, uint8_t share_mode) {
    using ProcessVmCategory = memory::ProcessVmCategory;
    switch (tag) {
      case VM_MEMORY_MALLOC_SMALL:
        return ProcessVmCategory::kMallocSmall;
      case VM_MEMORY_MALLOC_LARGE:
      case VM_MEMORY_MALLOC_HUGE:
      case VM_MEMORY_MALLOC_LARGE_REUSABLE:
      case VM_MEMORY_MALLOC_LARGE_REUSED:
        return ProcessVmCategory::kMallocLarge;
      case VM_MEMORY_MALLOC_TINY:
        return ProcessVmCategory::kMallocTiny;
      case VM_MEMORY_MALLOC_NANO:
        return ProcessVmCategory::kMallocNano;
      case VM_MEMORY_MALLOC_MEDIUM:
        return ProcessVmCategory::kMallocMedium;
      case VM_MEMORY_MALLOC:
      case VM_MEMORY_REALLOC:
      case VM_MEMORY_SBRK:
      case VM_MEMORY_MALLOC_PROB_GUARD:
        return ProcessVmCategory::kMallocOther;
      case VM_MEMORY_IOSURFACE:
        return ProcessVmCategory::kIosurface;
      case VM_MEMORY_IOKIT:
        return ProcessVmCategory::kIokit;
      case VM_MEMORY_STACK:
        return ProcessVmCategory::kStack;
      default:
        break;
    }
    if (share_mode == SM_SHARED || share_mode == SM_TRUESHARED || share_mode == SM_SHARED_ALIASED) {
      return ProcessVmCategory::kShared;
    }
    return tag == 0 ? ProcessVmCategory::kUntaggedPrivate : ProcessVmCategory::kOther;
  };

  const uint64_t page_size = snapshot.page_size ? snapshot.page_size : uint64_t(vm_page_size);
  mach_vm_address_t address = 0;
  natural_t depth = 0;
  while (true) {
    mach_vm_size_t size = 0;
    vm_region_submap_info_data_64_t info{};
    mach_msg_type_number_t info_count = VM_REGION_SUBMAP_INFO_COUNT_64;
    const kern_return_t result =
        mach_vm_region_recurse(mach_task_self(), &address, &size, &depth,
                               reinterpret_cast<vm_region_recurse_info_t>(&info), &info_count);
    if (result != KERN_SUCCESS) {
      snapshot.vm_region_scan_complete = result == KERN_INVALID_ADDRESS;
      snapshot.vm_region_scan_errors += result != KERN_INVALID_ADDRESS;
      break;
    }
    if (info.is_submap) {
      ++depth;
      continue;
    }
    memory::ProcessVmRegionUsage& usage =
        snapshot.vm_regions[size_t(classify_region(info.user_tag, info.share_mode))];
    usage.virtual_bytes += size;
    usage.resident_bytes += uint64_t(info.pages_resident) * page_size;
    usage.dirtied_bytes += uint64_t(info.pages_dirtied) * page_size;
    usage.swapped_bytes += uint64_t(info.pages_swapped_out) * page_size;
    ++usage.region_count;
    if (!size || address > std::numeric_limits<mach_vm_address_t>::max() - size) {
      ++snapshot.vm_region_scan_errors;
      break;
    }
    address += size;
  }
#endif
  return snapshot;
}

void ApplyNativeProcessMemorySnapshot(memory::Snapshot& destination,
                                      const NativeProcessMemorySnapshot& source,
                                      bool include_vm_regions) {
  destination.process_physical_footprint_bytes = source.physical_footprint_bytes;
  destination.process_physical_footprint_peak_bytes = source.physical_footprint_peak_bytes;
  destination.process_resident_bytes = source.resident_bytes;
  destination.process_resident_peak_bytes = source.resident_peak_bytes;
  destination.process_virtual_bytes = source.virtual_bytes;
  destination.process_internal_bytes = source.internal_bytes;
  destination.process_internal_peak_bytes = source.internal_peak_bytes;
  destination.process_external_bytes = source.external_bytes;
  destination.process_external_peak_bytes = source.external_peak_bytes;
  destination.process_reusable_bytes = source.reusable_bytes;
  destination.process_reusable_peak_bytes = source.reusable_peak_bytes;
  destination.process_compressed_bytes = source.compressed_bytes;
  destination.process_compressed_peak_bytes = source.compressed_peak_bytes;
  destination.process_device_bytes = source.device_bytes;
  destination.process_device_peak_bytes = source.device_peak_bytes;
  destination.process_graphics_footprint_bytes = source.graphics_footprint_bytes;
  destination.process_graphics_footprint_compressed_bytes =
      source.graphics_footprint_compressed_bytes;
  destination.process_graphics_nofootprint_bytes = source.graphics_nofootprint_bytes;
  destination.process_graphics_nofootprint_compressed_bytes =
      source.graphics_nofootprint_compressed_bytes;
  destination.process_limit_bytes_remaining = source.limit_bytes_remaining;
  destination.process_region_count = source.region_count;
  destination.process_page_size = source.page_size;
  destination.process_malloc_blocks_in_use = source.malloc_blocks_in_use;
  destination.process_malloc_in_use_bytes = source.malloc_in_use_bytes;
  destination.process_malloc_peak_bytes = source.malloc_peak_bytes;
  destination.process_malloc_reserved_bytes = source.malloc_reserved_bytes;
  destination.process_task_info_revision = source.task_info_revision;
  if (include_vm_regions) {
    destination.process_vm_region_scan_complete = source.vm_region_scan_complete;
    destination.process_vm_region_scan_errors = source.vm_region_scan_errors;
    destination.process_vm_regions = source.vm_regions;
  }
}

