uint64_t NextNativeTraceDiagnosticCount(std::atomic<uint64_t>& counter) {
  return counter.fetch_add(1, std::memory_order_relaxed) + 1;
}

template <typename Callable>
class ScopeExit {
 public:
  explicit ScopeExit(Callable&& callable) : callable_(std::move(callable)) {}
  ScopeExit(const ScopeExit&) = delete;
  ScopeExit& operator=(const ScopeExit&) = delete;
  ~ScopeExit() { callable_(); }

 private:
  Callable callable_;
};

template <typename Callable>
ScopeExit<Callable> MakeScopeExit(Callable&& callable) {
  return ScopeExit<Callable>(std::forward<Callable>(callable));
}



std::atomic<AntiAliasingMode> g_renderer_configured_anti_aliasing{AntiAliasingMode::kSmaa};
std::atomic<AntiAliasingMode> g_renderer_active_anti_aliasing{AntiAliasingMode::kSmaa};
std::atomic<bool> g_renderer_anti_aliasing_callback_registered{false};

const char* RendererAntiAliasingCompatibilityName(AntiAliasingCompatibility compatibility) {
  switch (compatibility) {
    case AntiAliasingCompatibility::kCanonical:
      return "canonical";
    case AntiAliasingCompatibility::kSpatialAlias:
      return "spatial-alias";
    case AntiAliasingCompatibility::kLegacySceneMsaa:
      return "legacy-scene-msaa";
    case AntiAliasingCompatibility::kLegacySpatialToggle:
      return "legacy-spatial-toggle";
    case AntiAliasingCompatibility::kFallbackOff:
      return "fallback-off";
  }
  return "fallback-off";
}

AntiAliasingMode ParseRendererAntiAliasingChange(std::string_view value,
                                                 AntiAliasingMode fallback) {
  if (const auto canonical = ParseAntiAliasingMode(value)) {
    return *canonical;
  }
  if (value == "spatial") {
    return AntiAliasingMode::kFxaa;
  }
  return fallback;
}

void OnRendererAntiAliasingChanged(std::string_view, std::string_view value) {
  const AntiAliasingMode previous_configured =
      g_renderer_configured_anti_aliasing.load(std::memory_order_acquire);
  const AntiAliasingMode requested = ParseRendererAntiAliasingChange(value, previous_configured);
  if (requested == previous_configured && value != AntiAliasingModeName(requested) &&
      value != "spatial") {
    REXLOG_ERROR("AAPolicy owner=renderer event=reject requested={}", value);
    return;
  }
  const AntiAliasingMode active = g_renderer_active_anti_aliasing.load(std::memory_order_acquire);
  const bool apply_live = CanApplyAntiAliasingLive(active, requested);
  g_renderer_configured_anti_aliasing.store(requested, std::memory_order_release);
  if (apply_live) {
    g_renderer_active_anti_aliasing.store(requested, std::memory_order_release);
  }
  const AntiAliasingMode resulting_active =
      g_renderer_active_anti_aliasing.load(std::memory_order_acquire);
  const auto route = GetAntiAliasingRoute(resulting_active);
  REXLOG_INFO(
      "AAPolicy owner=renderer event=set previous-configured={} requested={} "
      "active-before={} active-after={} apply={} route-fxaa={} route-smaa={} scene-samples={} "
      "ssaa-factor={}",
      AntiAliasingModeName(previous_configured), AntiAliasingModeName(requested),
      AntiAliasingModeName(active), AntiAliasingModeName(resulting_active),
      apply_live ? "live" : "restart", route.presentation_fxaa, route.presentation_smaa,
      route.scene_sample_count, route.supersampling_pixel_factor);
}

void InitializeRendererAntiAliasingController() {
  const std::string configured = rex::cvar::Query<std::string>("xnative_anti_aliasing");
  const std::string legacy_scene_msaa = REXCVAR_GET(xnative_msaa);
  const bool legacy_spatial = REXCVAR_GET(xnative_spatial_aa);
  const bool unified = rex::cvar::Query<bool>("xnative_anti_aliasing_unified");
  const auto resolved =
      ResolveAntiAliasingConfiguration(configured, legacy_scene_msaa, legacy_spatial, unified);
  g_renderer_configured_anti_aliasing.store(resolved.mode, std::memory_order_release);
  g_renderer_active_anti_aliasing.store(resolved.mode, std::memory_order_release);
  const auto route = GetAntiAliasingRoute(resolved.mode);
  REXLOG_INFO(
      "AAPolicy owner=renderer event=initialize configured-raw={} legacy-msaa={} "
      "legacy-spatial={} unified={} configured={} active={} compatibility={} "
      "ignored-legacy-msaa={} route-fxaa={} route-smaa={} scene-samples={} ssaa-factor={}",
      configured, legacy_scene_msaa, legacy_spatial, unified, AntiAliasingModeName(resolved.mode),
      AntiAliasingModeName(resolved.mode),
      RendererAntiAliasingCompatibilityName(resolved.compatibility),
      resolved.ignored_legacy_scene_msaa, route.presentation_fxaa, route.presentation_smaa,
      route.scene_sample_count, route.supersampling_pixel_factor);

  if (!g_renderer_anti_aliasing_callback_registered.exchange(true, std::memory_order_acq_rel)) {
    rex::cvar::RegisterChangeCallback("xnative_anti_aliasing", OnRendererAntiAliasingChanged);
  }
}

uint32_t GetNativePresentationAABits() {
  return GetAntiAliasingRoute(g_renderer_active_anti_aliasing.load(std::memory_order_acquire))
                 .presentation_fxaa
             ? 16u
             : 0u;
}

bool IsNativeSmaaEnabled() {
  return GetAntiAliasingRoute(g_renderer_active_anti_aliasing.load(std::memory_order_acquire))
      .presentation_smaa;
}

bool IsNativeSsaaEnabled() {
  return GetAntiAliasingRoute(g_renderer_active_anti_aliasing.load(std::memory_order_acquire))
             .supersampling_pixel_factor > 1u;
}

