constexpr uint32_t kPixelBooleansOffset = DeviceOffset(0x2790);
// Xcompiler (Halo 3): the last word of each half (vertex b96-b127, pixel b224-b255): its water
// vertex shader tests b101-b104.
constexpr uint32_t kVertexBooleansHighOffset = DeviceOffset(0x278C);
constexpr uint32_t kPixelBooleansHighOffset = DeviceOffset(0x279C);
// Xcompiler (Halo 3): the device keeps the Xenos flow constants as the GPU does (registers
// 0x4900-0x4927): 8 boolean words at 0x2780, then the 32 loop constants at 0x27A0-0x281F (the next
// field the D3D functions use is 0x2820).
constexpr uint32_t kLoopConstantsOffset = DeviceOffset(0x27A0);
constexpr uint32_t kLoopConstantCount = 32;
// Generated xport_recomp.81.cpp proves the title's sub_82A41D58/sub_82A41E40
// setters copy 16 bytes per float register and OR the caller-supplied mask;
// their generated callers form that mask from 0x8000000000000000 shifted by
// (register >> 2). UnleashedRecomp gpu/video.cpp independently decodes the
// same Xenos masks with countl_zero/countr_zero, confirming MSB-first order
// and one bit per four registers.
// Python verification: 4 * 16 = 64 bytes, 0x1000 / 64 = 64 VS groups,
// 0xE00 / 64 = 56 PS groups, so PS occupies dirty-word bits 63 through 8.
constexpr uint32_t kNativeConstantGroupBytes = 64;
constexpr std::array<DirtyBitSpan, 1> kVertexConstantDirtySpans{{{0, 0, 64, 0, true}}};
constexpr std::array<DirtyBitSpan, 1> kBooleanConstantDirtySpans{{{4, 56, 1, 0}}};
#if (XPORT_TITLE_ID == 0x4D5307E6)
// Xcompiler (Halo 3): all 256 pixel registers. The device keeps them at 0x1780-0x277F (booleans
// follow) and Halo uses c224-c255 (the final composite's color matrix and exposure, c229-c232):
// with 224 they read 0 and the world was black. Groups 56-63 are dirty bits 7-0.
constexpr std::array<DirtyBitSpan, 1> kPixelConstantDirtySpans{{{1, 0, 64, 0, true}}};
constexpr uint32_t kPixelConstantsSize = 0x1000;
constexpr uint32_t kPixelConstantGroups = 64;
#else
constexpr std::array<DirtyBitSpan, 1> kPixelConstantDirtySpans{{{1, 8, 56, 0, true}}};
constexpr uint32_t kPixelConstantsSize = 0xE00;
constexpr uint32_t kPixelConstantGroups = 56;
#endif
// Python verification: VS, PS, and shared blocks are respectively 4,096,
// 3,584, and 1,056 bytes, all exact multiples of the 16-byte BDA alignment.
// A draw with three unique versions therefore reserves exactly 8,736 bytes.
// 64 bytes: constant bank versions double as dynamic uniform-buffer offsets
// (minUniformBufferOffsetAlignment on Adreno); still a whole number of registers.
inline VkDeviceSize NativeConstantArenaAlignment() {
  // 64 bytes lets bank versions double as dynamic uniform-buffer offsets.
  static const bool align64 = REXCVAR_GET(xnative_constant_align64);
  return align64 ? 64 : 16;
}
static_assert(kVertexConstantsSize % NativeConstantUploadTracker::kRegisterBytes == 0);
static_assert(kPixelConstantsSize % NativeConstantUploadTracker::kRegisterBytes == 0);
constexpr VkDeviceSize kNativeConstantArenaMinimumSize = 0x10000;
constexpr VkDeviceSize kNativeConstantArenaGrowthGranularity = 0x10000;

constexpr DirtyStateLayout NativeConstantDirtyLayout() {
  DirtyStateLayout layout{};
  layout.vertex_constants = {kVertexConstantDirtySpans, 64};
  layout.pixel_constants = {kPixelConstantDirtySpans, kPixelConstantGroups};
  layout.boolean_constants = {kBooleanConstantDirtySpans, 1};
  return layout;
}
