const ShaderCacheEntry* FindStockShaderCacheEntry(uint64_t hash) {
  hash = CanonicalShaderHash(hash);  // rex/graphics/xnative/shader_aliases.h
  const ShaderCacheEntry* entry_begin = g_shaderCacheEntries;
  const ShaderCacheEntry* entry_end = entry_begin + g_shaderCacheEntryCount;
  const ShaderCacheEntry* entry = std::lower_bound(
      entry_begin, entry_end, hash, [](const ShaderCacheEntry& candidate, uint64_t candidate_hash) {
        return candidate.hash < candidate_hash;
      });
  return entry != entry_end && entry->hash == hash ? entry : nullptr;
}

bool StockShaderCacheEntryMatchesStage(const ShaderCacheEntry& entry, ShaderStage stage) {
  const bool filename_is_vertex = std::strstr(entry.filename, "_vs") != nullptr;
  const bool filename_is_pixel = std::strstr(entry.filename, "_ps") != nullptr;
  return !((stage == ShaderStage::kVertex && filename_is_pixel && !filename_is_vertex) ||
           (stage == ShaderStage::kPixel && filename_is_vertex && !filename_is_pixel));
}
